from dataclasses import dataclass, field


@dataclass
class Node:
    """A block or inline node; raw content is retained for later stages."""

    type: str
    children: list["Node"] = field(default_factory=list)
    raw: str = ""

    @property
    def raw_content(self) -> str:
        """Raw block content, available to the later inline parsing stage."""
        return self.raw


@dataclass
class Document:
    """Block tree plus normalized, document-wide reference definitions."""

    children: list[Node] = field(default_factory=list)
    references: dict[str, tuple[str, str]] = field(default_factory=dict)
from .model import Document, Node
import re


_THEMATIC_BREAK = re.compile(r"(?:\*\s*){3,}|(?:-\s*){3,}|(?:_\s*){3,}\Z")


def _indent_columns(line: str) -> tuple[int, int]:
    """Return indentation columns and the character offset after indentation."""
    columns = 0
    offset = 0
    while offset < len(line) and line[offset] in " \t":
        if line[offset] == "\t":
            columns += 4 - columns % 4
        else:
            columns += 1
        offset += 1
    return columns, offset


def _is_thematic_break(line: str) -> bool:
    columns, offset = _indent_columns(line)
    return columns <= 3 and bool(_THEMATIC_BREAK.fullmatch(line[offset:]))


def parse_blocks(markdown: str) -> Document:
    """Parse paragraphs, blank lines, and thematic breaks."""
    source = markdown.replace("\x00", "\ufffd").replace("\r\n", "\n").replace("\r", "\n")
    children = []
    paragraph: list[str] = []

    def flush_paragraph() -> None:
        if paragraph:
            raw = "\n".join(paragraph).strip(" \t")
            if raw:
                children.append(Node("paragraph", raw=raw))
            paragraph.clear()

    for line in source.split("\n"):
        if not line.strip(" \t"):
            flush_paragraph()
            continue
        if _is_thematic_break(line):
            flush_paragraph()
            children.append(Node("thematic_break"))
            continue
        columns, offset = _indent_columns(line)
        # Up to three columns of indentation are block indentation, not content.
        if columns <= 3:
            line = line[offset:]
        paragraph.append(line)
    flush_paragraph()
    return Document(children=children)


def parse_inlines(document: Document) -> Document:
    """Inline stage; preserves the shared document until syntax is implemented."""
    return document


def render_html(document: Document) -> str:
    """Render an empty document as empty HTML."""
